<?php
declare(strict_types=1);
if (!defined('CWP_BOOT')) { http_response_code(404); exit; }

 $l=one('SELECT * FROM '.table('leads').' WHERE id=?',[$id]);if(!$l){echo '<div class="notice error">Inquiry not found.</div>';admin_foot();exit;}
 if($l['service']==='Consultation request')echo '<p><a class="btn outline" href="'.esc(admin_url('consultation',['id'=>$id])).'">Consultation appointment and history</a></p>';
 if($l['service']==='Website review')echo '<p><a class="btn outline" href="'.esc(admin_url('website-review',['id'=>$id])).'">Website review report and history</a></p>';
 ?><div class="admin-toolbar"><p><?=esc($l['reference'])?> · Received <?=esc($l['created_at'])?> UTC</p><a class="btn gold small" href="mailto:<?=esc($l['email'])?>?subject=<?=rawurlencode('Your website project · '.$l['reference'])?>">Reply by Email ↗</a></div><div class="editor-layout"><div><section class="admin-card"><div class="card-header"><h2><?=esc($l['name'])?></h2><?=badge($l['status'])?></div><dl class="lead-facts"><?php foreach(['email'=>'Email','company'=>'Business','phone'=>'Phone','service'=>'Service','budget'=>'Budget','timeline'=>'Timeline'] as $key=>$label):?><div><dt><?=$label?></dt><dd><?=esc($l[$key]?:'Not supplied')?></dd></div><?php endforeach;?></dl><h3 class="subheading">The project</h3><div class="prose inquiry-message"><?=nl2br(esc($l['message']))?></div><p class="hint">Privacy notice acknowledged with this inquiry: <?=$l['consent']?'Yes':'No'?>.</p></section><form class="admin-card" method="post" action="<?=esc(admin_url('lead',['id'=>$id]))?>"><?php admin_action('lead_save');?><input type="hidden" name="id" value="<?=$id?>"><?php admin_select('status','Inquiry status',pipeline_choices($l['status']),$l['status']);admin_textarea('notes','Private studio notes',$l['notes'],6,12000);?><button class="btn gold">Save Inquiry →</button></form><?php $history=pipeline_history($id);if($history):?><section class="admin-card"><h3>Stage history</h3><ul class="history-list"><?php foreach($history as $h):?><li><strong><?=esc(studio_pipeline_stages()[$h['from_stage']]??$h['from_stage'])?> → <?=esc(studio_pipeline_stages()[$h['to_stage']]??$h['to_stage'])?></strong><small><?=esc(($h['actor_name']??'system').' · '.$h['created_at'])?> UTC</small></li><?php endforeach;?></ul></section><?php endif;?></div><aside><section class="admin-card"><div class="card-header"><h2>Notification</h2></div><?=badge($l['notification_status'])?><p class="hint spaced">“Accepted” means the mail service accepted the message, not that inbox delivery has been confirmed. The inquiry is saved regardless.</p><form method="post" action="<?=esc(admin_url('lead',['id'=>$id]))?>"><?php admin_action('lead_retry');?><input type="hidden" name="id" value="<?=$id?>"><button class="btn outline small">Resend Notification ↻</button></form></section><section class="admin-card"><h3>Manage this record</h3><p class="hint spaced">Review retention needs and remove records when they are no longer required. Deletion is permanent.</p><form method="post" action="<?=esc(admin_url('lead',['id'=>$id]))?>" data-confirm="Permanently delete this inquiry, private notes and any linked review reports, appointments and history? This cannot be undone."><?php admin_action('lead_delete');?><input type="hidden" name="id" value="<?=$id?>"><button class="btn danger small">Delete Inquiry</button></form></section></aside></div><?php
